def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def is_num(x):
        return isinstance(x, (int, float))

    def to_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1]):
            return (x[0], x[1])
        return None

    def get_my_pos(obs):
        for k in ("position", "pos", "agent_pos", "agent_position", "self_pos", "location"):
            p = to_pos(obs.get(k))
            if p is not None:
                return p
        me = obs.get("self")
        if isinstance(me, dict):
            for k in ("position", "pos", "agent_pos", "location"):
                p = to_pos(me.get(k))
                if p is not None:
                    return p
        agents = obs.get("agents")
        if isinstance(agents, dict):
            for k in ("me", "self", "agent"):
                a = agents.get(k)
                if isinstance(a, dict):
                    for kk in ("position", "pos", "location"):
                        p = to_pos(a.get(kk))
                        if p is not None:
                            return p
        return (0, 0)

    def extract_points(obj):
        pts = []
        if obj is None:
            return pts
        p = to_pos(obj)
        if p is not None:
            return [p]
        if isinstance(obj, dict):
            for v in obj.values():
                pts.extend(extract_points(v))
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                pts.extend(extract_points(v))
        return pts

    def nearest(points, x, y):
        best = None
        best_d = None
        for px, py in points:
            d = abs(px - x) + abs(py - y)
            if best_d is None or d < best_d:
                best_d = d
                best = (px, py, d)
        return best

    obs = observation if isinstance(observation, dict) else {}
    x, y = get_my_pos(obs)

    resources = []
    for k in ("resources", "resource_positions", "resource_tiles", "items", "food", "minerals"):
        resources.extend(extract_points(obs.get(k)))

    enemies = []
    for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "threats"):
        enemies.extend(extract_points(obs.get(k)))

    targets = []
    for k in ("goals", "goal_positions", "targets", "target_positions", "bases", "base_positions", "objectives", "territories"):
        targets.extend(extract_points(obs.get(k)))

    allies = []
    for k in ("allies", "friendly_positions", "teammates", "team"):
        allies.extend(extract_points(obs.get(k)))

    task = obs.get("task") or obs.get("mode") or obs.get("scenario") or ""
    task = str(task).lower() if task is not None else ""

    if not targets:
        targets = resources[:]
    if not resources:
        resources = targets[:]

    actions = [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1)]
    best_action = (0, 0)
    best_score = None

    for dx, dy in actions:
        nx, ny = x + dx, y + dy
        score = 0.0

        # Prefer motion over standing still unless advantageous
        if dx == 0 and dy == 0:
            score -= 0.2

        if resources:
            r = nearest(resources, nx, ny)
            if r is not None:
                score += 6.0 / (1.0 + r[2])

        if targets:
            t = nearest(targets, nx, ny)
            if t is not None:
                score += 5.0 / (1.0 + t[2])

        if enemies:
            e = nearest(enemies, nx, ny)
            if e is not None:
                d = e[2]
                if "pursuit" in task or "evade" in task:
                    score += 1.5 * d if d <= 4 else 0.2 * d
                    if d == 0:
                        score -= 8.0
                else:
                    score -= 4.5 / (1.0 + d)
                    if d <= 1:
                        score -= 3.0

        if allies:
            a = nearest(allies, nx, ny)
            if a is not None:
                score += 0.5 / (1.0 + a[2])

        # Mild center preference if nothing else
        if not resources and not targets and not enemies:
            score -= abs(nx) + abs(ny)

        if best_score is None or score > best_score:
            best_score = score
            best_action = (dx, dy)

    return [clamp(best_action[0]), clamp(best_action[1])]

